from google.cloud import documentai

def get_documentai_client(location: str):
    return documentai.DocumentProcessorServiceClient(
        client_options={"api_endpoint": f"{location}-documentai.googleapis.com"})

from google.cloud import documentai
from document_client import get_documentai_client

def extract_tables(payload, config=None):
    config = config or {}
    client = get_documentai_client(config['location'])
    name = client.processor_path(config["project_id"], config["location"], config["processor_id"])
    response = client.process_document(request={"name": name, "raw_document": documentai.RawDocument(
        content=payload["document_bytes"], mime_type=payload["mime_type"])})

    tables_data = []
    for page in response.document.pages:
        for table in page.tables:
            table_cells = []
            for row in table.body_rows:
                row_cells = []
                for cell in row.cells:
                    # Extract text content for each cell
                    cell_text = response.document.text[cell.layout.text_anchor.text_segments[0].start_index:cell.layout.text_anchor.text_segments[0].end_index]
                    row_cells.append(cell_text)
                table_cells.append(row_cells)
            tables_data.append({"page_number": page.page_number, "cells": table_cells})

    return {"tables": tables_data, "full_text": response.document.text}

from google.cloud import documentai
from document_client import get_documentai_client

def extract_key_values(payload, config=None):
    config = config or {}
    client = get_documentai_client(config['location'])
    name = client.processor_path(config["project_id"], config["location"], config["processor_id"])
    response = client.process_document(request={"name": name, "raw_document": documentai.RawDocument(
        content=payload["document_bytes"], mime_type=payload["mime_type"])})

    key_value_pairs = []
    for page in response.document.pages:
        for form_field in page.form_fields:
            key = response.document.text[form_field.field_name.text_segments[0].start_index:form_field.field_name.text_segments[0].end_index]
            value = response.document.text[form_field.field_value.text_segments[0].start_index:form_field.field_value.text_segments[0].end_index]
            key_value_pairs.append({"key": key, "value": value, "page_number": page.page_number})

    return {"key_value_pairs": key_value_pairs, "full_text": response.document.text}

from google.cloud import translate_v2 as translate

def ocr_translate(payload, config=None):
    config = config or {}
    translate_client = translate.Client()

    text_to_translate = payload["text"]
    target_language = config.get("target_language", "en")

    result = translate_client.translate(text_to_translate, target_language=target_language)

    return {
        "translated_text": result["translatedText"],
        "source_language": result["detectedSourceLanguage"],
        "original_text": text_to_translate
    }

import google.generativeai as genai
import json

def document_field_extraction(payload, config=None):
    config = config or {}
    genai.configure(api_key=config["gemini_api_key"])
    model = genai.GenerativeModel('gemini-pro')

    document_text = payload["text"]

    # Example of a prompt for extracting structured fields. 
    # The actual fields to extract would be defined by the user/task.
    prompt = f"""Extract the following fields from the document text as a JSON object. If a field is not found, use null.
Expected fields: InvoiceNumber, TotalAmount, IssueDate, VendorName, CustomerName.

Document Text:
{document_text}

JSON Output:"""

    response = model.generate_content(prompt)

    try:
        extracted_fields = json.loads(response.text.strip())
    except json.JSONDecodeError:
        extracted_fields = {"error": "Could not parse JSON from model response", "raw_response": response.text}

    return {"extracted_fields": extracted_fields, "original_text": document_text}

import google.generativeai as genai

def ocr_embedding(payload, config=None):
    config = config or {}
    genai.configure(api_key=config["gemini_api_key"])

    text_to_embed = payload["text"]

    # The embedding model can be specified. For text, text-embedding-004 is a good choice.
    model_name = config.get("embedding_model", "models/embedding-001")

    result = genai.embed_content(model=model_name, content=text_to_embed)

    return {"embedding": result['embedding'], "original_text": text_to_embed}
